import { Dialog as DialogPrimitive } from "@base-ui/react/dialog";
import { cn } from "cn";
import {
  ChevronLeft,
  ChevronRight,
  RotateCcw,
  RotateCcwSquare,
  RotateCw,
  X,
  ZoomIn,
  ZoomOut,
} from "lucide-react";
import {
  type ComponentProps,
  type PointerEvent,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import type { GlassProps } from "@/lib/glass/with-glass";
import {
  clampImageScale,
  defaultImageTransform,
  normalizeImageIndex,
  wrapImageIndex,
} from "@/lib/viewer/image-transform";
import { Button } from "@/components/ui/button";
import { Dialog, DialogOverlay, DialogTitle } from "@/components/ui/dialog";
import { ViewerButton } from "@/components/ui/viewer/controls";

export type ImageViewerLabels = {
  defaultAlt: string;
  viewer: string;
  zoomOut: string;
  zoomIn: string;
  rotateCounterclockwise: string;
  rotateClockwise: string;
  reset: string;
  close: string;
  previous: string;
  next: string;
  loading: string;
  error: string;
  retry: string;
  imageAlt: (alt: string, index: number) => string;
  open: (alt: string, index: number) => string;
  thumbnail: (alt: string, index: number) => string;
  position: (index: number, total: number) => string;
};
export interface ImageViewerProps extends GlassProps {
  images: string | string[];
  open: boolean;
  onClose: () => void;
  index?: number;
  initialIndex?: number;
  onIndexChange?: (index: number) => void;
  alt?: string;
  container?: ComponentProps<typeof DialogPrimitive.Portal>["container"];
  className?: string;
  labels?: Partial<ImageViewerLabels>;
}
const defaultLabels: ImageViewerLabels = {
  defaultAlt: "Image",
  viewer: "Image viewer",
  zoomOut: "Zoom out",
  zoomIn: "Zoom in",
  rotateCounterclockwise: "Rotate counterclockwise",
  rotateClockwise: "Rotate clockwise",
  reset: "Reset image",
  close: "Close image viewer",
  previous: "Previous image",
  next: "Next image",
  loading: "Loading image…",
  error: "Unable to load image",
  retry: "Retry",
  imageAlt: (alt, index) => `${alt} ${index}`,
  open: (alt, index) => `Open ${alt} ${index}`,
  thumbnail: (alt, index) => `${alt} thumbnail ${index}`,
  position: (index, total) => `Image ${index} of ${total}`,
};
function ImageViewer({
  images,
  open,
  onClose,
  index: controlledIndex,
  initialIndex = 0,
  onIndexChange,
  alt,
  container,
  className,
  glass,
  frosted,
  labels,
}: ImageViewerProps) {
  // glass and frosted apply to the toolbar and navigation buttons.
  const material = { glass, frosted };
  const text = { ...defaultLabels, ...labels };
  const list = Array.isArray(images) ? images : [images];
  const [localIndex, setIndex] = useState(initialIndex);
  const index = normalizeImageIndex(controlledIndex ?? localIndex, list.length);
  const [transform, setTransform] = useState(defaultImageTransform);
  const [dragging, setDragging] = useState(false);
  const reducedMotion = useReducedMotion();
  const close = onClose;
  const imageRef = useRef<HTMLImageElement>(null);
  const pointers = useRef(new Map<number, { x: number; y: number }>());
  const gesture = useRef<{
    x: number;
    y: number;
    tx: number;
    ty: number;
    distance: number;
    scale: number;
  } | null>(null);
  const [retry, setRetry] = useState(0);
  const key = `${index}\u0000${list[index]}\u0000${retry}`;
  const [load, setLoad] = useState<{
    key: string;
    state: "ready" | "error";
  } | null>(null);
  const state = load?.key === key ? load.state : "loading";
  const reset = useCallback(() => {
    setTransform(defaultImageTransform);
    pointers.current.clear();
    gesture.current = null;
    setDragging(false);
  }, []);
  const select = useCallback(
    (next: number) => {
      if (!list.length) return;
      const value = wrapImageIndex(next, list.length);
      if (controlledIndex === undefined) setIndex(value);
      onIndexChange?.(value);
      reset();
    },
    [controlledIndex, list.length, onIndexChange, reset],
  );
  function zoomBy(delta: number) {
    setTransform((previous) => ({
      ...previous,
      scale: clampImageScale(previous.scale + delta),
    }));
  }
  function rotateBy(delta: number) {
    setTransform((previous) => ({
      ...previous,
      rotate: previous.rotate + delta,
    }));
  }
  useEffect(() => {
    if (open && controlledIndex === undefined) setIndex(initialIndex);
    reset();
  }, [open, controlledIndex, initialIndex, reset]);
  useEffect(() => {
    void key;
    reset();
  }, [key, reset]);
  useEffect(() => {
    if (!open) return;
    const image = imageRef.current;
    if (image?.complete)
      setLoad({ key, state: image.naturalWidth > 0 ? "ready" : "error" });
  }, [open, key]);
  function beginGesture() {
    const values = [...pointers.current.values()];
    if (!values.length) {
      gesture.current = null;
      setDragging(false);
      return;
    }
    const a = values[0];
    const b = values[1];
    gesture.current = {
      x: b ? (a.x + b.x) / 2 : a.x,
      y: b ? (a.y + b.y) / 2 : a.y,
      tx: transform.x,
      ty: transform.y,
      distance: b ? Math.hypot(a.x - b.x, a.y - b.y) : 0,
      scale: transform.scale,
    };
    setDragging(true);
  }
  const wheelRef = useCallback((node: HTMLDivElement | null) => {
    if (!node) return;
    const onWheel = (event: WheelEvent) => {
      event.preventDefault();
      // Zoom follows the wheel distance: trackpads glide in small steps, and
      // a mouse notch (about 100px) still zooms by roughly a quarter.
      const unit = [1, 16, window.innerHeight][event.deltaMode] ?? 1;
      const factor = Math.exp((-event.deltaY * unit) / 400);
      setTransform((previous) => ({
        ...previous,
        scale: clampImageScale(previous.scale * factor),
      }));
    };
    node.addEventListener("wheel", onWheel, { passive: false });
    return () => node.removeEventListener("wheel", onWheel);
  }, []);
  function onPointerDown(event: PointerEvent<HTMLDivElement>) {
