      event.button !== 0 ||
      state !== "ready" ||
      (event.target instanceof Element && event.target.closest("button"))
    )
      return;
    event.currentTarget.setPointerCapture?.(event.pointerId);
    pointers.current.set(event.pointerId, {
      x: event.clientX,
      y: event.clientY,
    });
    beginGesture();
  }
  function onPointerMove(event: PointerEvent<HTMLDivElement>) {
    if (!pointers.current.has(event.pointerId) || !gesture.current) return;
    pointers.current.set(event.pointerId, {
      x: event.clientX,
      y: event.clientY,
    });
    const [a, b] = [...pointers.current.values()];
    const start = gesture.current;
    setTransform((previous) => ({
      ...previous,
      x: start.tx + (b ? (a.x + b.x) / 2 : a.x) - start.x,
      y: start.ty + (b ? (a.y + b.y) / 2 : a.y) - start.y,
      scale:
        b && start.distance > 0
          ? clampImageScale(
              (start.scale * Math.hypot(a.x - b.x, a.y - b.y)) / start.distance,
            )
          : previous.scale,
    }));
  }
  function onPointerEnd(event: PointerEvent<HTMLDivElement>) {
    pointers.current.delete(event.pointerId);
    beginGesture();
  }
  if (!list.length) return null;
  const resolvedAlt = alt ?? text.defaultAlt;
  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        if (!next) close();
      }}
    >
      <DialogPrimitive.Portal container={container}>
        <DialogOverlay />
        <DialogPrimitive.Popup
          data-slot="image-viewer"
          aria-describedby={undefined}
          className={cn(
            "fixed inset-0 z-50 flex h-dvh w-screen flex-col bg-background text-foreground text-sm outline-none",
            className,
          )}
          onKeyDown={(event) => {
            if (
              event.target instanceof Element &&
              event.target.closest(
                "input,textarea,select,[contenteditable=true]",
              )
            )
              return;
            if (event.key === "ArrowLeft") {
              event.preventDefault();
              select(index - 1);
            } else if (event.key === "ArrowRight") {
              event.preventDefault();
              select(index + 1);
            } else if (event.key === "+" || event.key === "=") {
              event.preventDefault();
              zoomBy(0.25);
            } else if (event.key === "-") {
              event.preventDefault();
              zoomBy(-0.25);
            } else if (event.key === "0") {
              event.preventDefault();
              reset();
            }
          }}
        >
          <DialogTitle className="sr-only">{text.viewer}</DialogTitle>
          <div className="flex shrink-0 flex-wrap items-center gap-1 px-3 py-2">
            <ViewerButton
              {...material}
              size="icon-sm"
              variant="ghost"
              tooltip={text.zoomOut}
              onClick={() => zoomBy(-0.25)}
            >
              <ZoomOut aria-hidden="true" />
            </ViewerButton>
            <span className="min-w-12 text-center tabular-nums">
              {Math.round(transform.scale * 100)}%
            </span>
            <ViewerButton
              {...material}
              size="icon-sm"
              variant="ghost"
              tooltip={text.zoomIn}
              onClick={() => zoomBy(0.25)}
            >
              <ZoomIn aria-hidden="true" />
            </ViewerButton>
            <ViewerButton
              {...material}
              size="icon-sm"
              variant="ghost"
              tooltip={text.rotateCounterclockwise}
              onClick={() => rotateBy(-90)}
            >
              <RotateCcw aria-hidden="true" />
            </ViewerButton>
            <ViewerButton
              {...material}
              size="icon-sm"
              variant="ghost"
              tooltip={text.rotateClockwise}
              onClick={() => rotateBy(90)}
            >
              <RotateCw aria-hidden="true" />
            </ViewerButton>
            <ViewerButton
              {...material}
              size="icon-sm"
              variant="ghost"
              tooltip={text.reset}
              disabled={
                transform.scale === 1 &&
                transform.rotate === 0 &&
                transform.x === 0 &&
                transform.y === 0
              }
              onClick={reset}
            >
              <RotateCcwSquare aria-hidden="true" />
            </ViewerButton>
            <span className="ms-auto text-muted-foreground tabular-nums">
              {index + 1} / {list.length}
            </span>
            <ViewerButton
              {...material}
              size="icon-sm"
              variant="ghost"
              tooltip={text.close}
              onClick={close}
            >
              <X aria-hidden="true" />
            </ViewerButton>
          </div>
          <span role="status" className="sr-only">
            {text.position(index + 1, list.length)}
          </span>
          <div
            ref={wheelRef}
            role="none"
            className={cn(
              "relative flex min-h-0 flex-1 touch-none items-center justify-center overflow-hidden",
              dragging ? "cursor-grabbing" : "cursor-grab",
            )}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerEnd}
            onPointerCancel={onPointerEnd}
            onLostPointerCapture={onPointerEnd}
          >
            {state === "loading" && <span role="status">{text.loading}</span>}
            {state === "error" && (
              <div className="flex flex-col items-center gap-3">
                <span role="alert" className="text-destructive">
                  {text.error}
                </span>
                <Button
                  variant="outline"
                  onClick={() => {
                    setLoad(null);
                    setRetry((previous) => previous + 1);
                  }}
                >
                  {text.retry}
                </Button>
              </div>
            )}
            <img
              ref={imageRef}
              key={key}
              src={list[index]}
              alt={text.imageAlt(resolvedAlt, index + 1)}
              draggable={false}
              onLoad={() => setLoad({ key, state: "ready" })}
              onError={() => setLoad({ key, state: "error" })}
              className={cn(
                "max-h-full max-w-full select-none object-contain",
                state !== "ready" && "absolute opacity-0",
              )}
              style={{
                transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale}) rotate(${transform.rotate}deg)`,
                transition:
                  dragging || reducedMotion ? "none" : "transform 150ms ease",
              }}
            />
            {list.length > 1 && (
              <>
                <Button
                  {...material}
                  variant="ghost"
                  size="icon"
                  className="absolute inset-s-3 z-10 bg-background/80"
                  onClick={() => select(index - 1)}
                  aria-label={text.previous}
                >
                  <ChevronLeft aria-hidden="true" />
                </Button>
                <Button
                  {...material}
                  variant="ghost"
                  size="icon"
                  className="absolute inset-e-3 z-10 bg-background/80"
                  onClick={() => select(index + 1)}
                  aria-label={text.next}
                >
                  <ChevronRight aria-hidden="true" />
                </Button>
              </>
            )}
          </div>
          {list.length > 1 && (
            <div
              data-slot="image-viewer-thumbnails"
              className="shrink-0 overflow-x-auto px-3 py-2"
            >
              <div className="mx-auto flex w-max gap-2">
                {list.map((src, imageIndex) => (
                  <Button
                    // biome-ignore lint/suspicious/noArrayIndexKey: Repeated URLs are distinct numbered gallery entries.
                    key={`${src}-${imageIndex}`}
                    variant="ghost"
                    size="icon"
                    className={cn(
                      "size-12 shrink-0 overflow-hidden rounded-lg p-0 ring-2 ring-transparent",
                      imageIndex === index
                        ? "ring-primary"
                        : "opacity-50 hover:opacity-80",
                    )}
                    aria-pressed={imageIndex === index}
                    aria-label={text.open(resolvedAlt, imageIndex + 1)}
                    onClick={() => select(imageIndex)}
                  >
                    <img
                      src={src}
                      alt={text.thumbnail(resolvedAlt, imageIndex + 1)}
                      className="size-full object-cover"
                    />
                  </Button>
                ))}
              </div>
            </div>
          )}
        </DialogPrimitive.Popup>
      </DialogPrimitive.Portal>
    </Dialog>
  );
}

