function useFrame(periodMs: number, reduce: boolean) {
  const [frame, setFrame] = useState(0);
  useEffect(() => {
    if (reduce) return;
    const timer = setInterval(
      () => setFrame((previous) => previous + 1),
      Math.max(10, periodMs),
    );
    return () => clearInterval(timer);
  }, [periodMs, reduce]);
  return reduce ? 0 : frame;
}

