import { MorphIcon as MorphIconPrimitive } from "morphicons/react";
import type { ComponentProps } from "react";

type MorphIconProps = ComponentProps<typeof MorphIconPrimitive>;

function MorphIcon({
  className,
  size = 16,
  strokeWidth = 2,
  spring = "snappy",
  reducedMotion = "user",
  ...props
}: MorphIconProps) {
