      "[data-tab-bar-item]",
    ) ?? []) {
      const content = button.querySelector("[data-tab-bar-content]");
      if (!content) continue;
      gsap.to(content, {
        scale:
          heldValue !== null &&
          button.dataset.held === "true" &&
          !reducedMotion.current
            ? 1.2
