import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";
import {
  ChevronDownIcon,
  ChevronLeftIcon,
  ChevronRightIcon,
  ChevronUpIcon,
} from "lucide-react";
import * as React from "react";
import { withGlass } from "@/lib/glass/with-glass";

const TabsContext =
