import * as React from "react";
import {
  type BottomSheetDetents,
  type BottomSheetLayout,
  type BottomSheetSize,
  bottomSheetDefaults,
  bottomSheetFrame,
  bottomSheetLayout,
  createVelocityTracker,
  resolveBottomSheetRelease,
} from "@/lib/bottom-sheet";

type BottomSheetControllerOptions = {
  open: boolean;
  size: BottomSheetSize;
  expandable: boolean;
  setSize: (size: BottomSheetSize) => void;
  setShape: (shape: Pick<BottomSheetLayout, "expandable" | "full">) => void;
  close: () => void;
  isOpen: () => boolean;
  detents: BottomSheetDetents;
  keyboard: "resize" | "lift";
  footerMode: "adaptive" | "fixed";
  expandOnInputFocus: boolean;
  contentKey: React.Key | undefined;
};

type Drag = {
  source: "handle" | "body";
  pointerId: number | null;
  startX: number;
  startY: number;
  startExtent: number;
  extent: number;
  from: BottomSheetSize;
  /** Pending until the press moves far enough to tell a drag from a scroll. */
  mode: "pending" | "drag" | "native";
};

/** Heights read once per measurement, so drag frames never read layout. */
type Chrome = { header: number; footer: number; natural: number };

const textField =
  'input:not([type="checkbox"],[type="radio"],[type="range"],[type="button"],[type="submit"],[type="reset"],[type="file"],[type="color"]),textarea,select,[contenteditable=""],[contenteditable="true"]';
// Fields, sliders, the footer and marked regions keep their own gestures.
const ownGesture = `${textField},input[type="range"],[role="slider"],[data-slot="bottom-sheet-footer"],[data-bottom-sheet-no-drag]`;
const handle =
  '[data-slot="bottom-sheet-header"],[data-slot="bottom-sheet-grabber"]';
const settleDelay = 450;

let progressRegistered = false;

/** Registers the progress variable as a number so it can animate. */
function registerProgress() {
  if (progressRegistered || typeof CSS === "undefined") return;
  progressRegistered = true;
  try {
    CSS.registerProperty?.({
      name: "--bottom-sheet-progress",
      syntax: "<number>",
      inherits: true,
      initialValue: "0",
    });
  } catch {
    // Already registered by another copy of the component.
  }
}

function part(container: HTMLElement, slot: "header" | "body" | "footer") {
  return container.querySelector<HTMLElement>(
    `:scope > [data-slot="bottom-sheet-${slot}"]`,
  );
}

/** The body scrolls, unless the whole container does when space is short. */
function scrollElement(container: HTMLElement) {
  if (container.dataset.scroll === "container") return container;
  return part(container, "body") ?? container;
}

function resetScroll(container: HTMLElement) {
  container.scrollTop = 0;
  const body = part(container, "body");
  if (body) body.scrollTop = 0;
}

// A collapsed header still reserves its full height in the layout.
function headerHeight(header: HTMLElement | null) {
  if (!header) return 0;
  if (header.hasAttribute("data-collapsed") && header.dataset.naturalHeight)
    return Number(header.dataset.naturalHeight);
  return header.offsetHeight;
}

function measureChrome(popup: HTMLElement, container: HTMLElement): Chrome {
  const styles = getComputedStyle(container);
  let natural =
    (Number.parseFloat(styles.paddingTop) || 0) +
    (Number.parseFloat(styles.paddingBottom) || 0) +
    popup.offsetHeight -
    popup.clientHeight;
  for (const child of Array.from(container.children)) {
    if (!(child instanceof HTMLElement)) continue;
    const slot = child.dataset.slot;
    if (slot === "bottom-sheet-header") natural += headerHeight(child);
    // The body may be scrolling, so its content height is its scroll height.
    else if (slot === "bottom-sheet-body") natural += child.scrollHeight;
    else natural += child.offsetHeight;
  }
  return {
    header: headerHeight(part(container, "header")),
    footer: part(container, "footer")?.offsetHeight ?? 0,
    natural,
  };
}

// Keeps a drag going outside the sheet; the pointer may already be gone.
function capture(element: HTMLElement, pointerId: number) {
  try {
    element.setPointerCapture(pointerId);
  } catch {
    // Released before the drag began.
  }
}

function keyboardInset() {
  const viewport = window.visualViewport;
  if (!viewport) return 0;
  const hidden = window.innerHeight - viewport.height - viewport.offsetTop;
  return Math.max(0, Math.round(hidden));
}

/** Coalesces calls into one per animation frame. */
function perFrame(callback: () => void) {
  let frame = 0;
  const schedule = () => {
    if (frame) return;
    frame = requestAnimationFrame(() => {
      frame = 0;
      callback();
    });
  };
  schedule.cancel = () => cancelAnimationFrame(frame);
  return schedule;
}

/**
 * Measures the sheet into sizes, paints its frame through CSS variables
 * and runs its drag, wheel and focus gestures.
 */
export function useBottomSheetController(
  options: BottomSheetControllerOptions,
) {
  const { open, size, expandable, setSize, setShape, contentKey } = options;
  const [popup, setPopup] = React.useState<HTMLDivElement | null>(null);
  const [settled, setSettled] = React.useState(false);
  const containerRef = React.useRef<HTMLDivElement>(null);
  const overlayRef = React.useRef<HTMLDivElement>(null);
  const probeRef = React.useRef<HTMLDivElement>(null);
  const optionsRef = React.useRef(options);
  optionsRef.current = options;
  const layoutRef = React.useRef<BottomSheetLayout>({
    heights: { default: 0, lg: 0 },
    expandable: false,
    full: false,
  });
  const chromeRef = React.useRef<Chrome>({ header: 0, footer: 0, natural: 0 });
  const dragRef = React.useRef<Drag | null>(null);

  const extentOf = React.useCallback(
    (target: BottomSheetSize) => layoutRef.current.heights[target],
    [],
  );

  // Only writes CSS variables, so it can run on every pointer move.
  const paint = React.useCallback(
    (extent: number) => {
      if (!popup) return;
      const frame = bottomSheetFrame(extent, layoutRef.current);
      const dismiss = Math.min(1, frame.offset / Math.max(1, frame.height));
      popup.style.setProperty("--bottom-sheet-height", `${frame.height}px`);
      popup.style.setProperty("--bottom-sheet-offset", `${frame.offset}px`);
      popup.style.setProperty("--bottom-sheet-progress", `${frame.progress}`);
      const overlay = overlayRef.current?.style;
      overlay?.setProperty("--bottom-sheet-progress", `${frame.progress}`);
      overlay?.setProperty("--bottom-sheet-dismiss", `${dismiss}`);
    },
    [popup],
  );

  // Chooses what scrolls: nothing until the sheet may scroll, then the body,
  // or the whole container when an adaptive footer leaves too little room.
  const scrollableRef = React.useRef(false);
  const flowsRef = React.useRef(false);
  const applyScroll = React.useCallback(() => {
    const container = containerRef.current;
    if (!container) return;
    let scroll = "none";
    if (scrollableRef.current) scroll = "body";
    if (scrollableRef.current && (flowsRef.current || !part(container, "body")))
      scroll = "container";
    container.dataset.scroll = scroll;
  }, []);

  // Rests at a size: paints it, then lets the footer flow if it must.
  const rest = React.useCallback(
    (target: BottomSheetSize) => {
      const height = extentOf(target);
      paint(height);
      const { header, footer } = chromeRef.current;
      flowsRef.current =
        optionsRef.current.footerMode === "adaptive" &&
        footer > 0 &&
        height - header - footer < bottomSheetDefaults.minimumBody;
      applyScroll();
    },
    [paint, extentOf, applyScroll],
  );

  const measure = React.useCallback(() => {
    const container = containerRef.current;
    const { isOpen, keyboard, detents } = optionsRef.current;
    if (!popup || !container || !isOpen()) return;
    const viewportHeight =
      popup.parentElement?.clientHeight ?? window.innerHeight;
    const room = viewportHeight - (probeRef.current?.offsetHeight ?? 0);
    const inset = keyboardInset();
    popup.style.setProperty("--bottom-sheet-keyboard", `${inset}px`);
    const chrome = measureChrome(popup, container);
    chromeRef.current = chrome;
    const layout = bottomSheetLayout({
      available: keyboard === "lift" ? room : room - inset,
      natural: chrome.natural,
      chrome: chrome.header + chrome.footer,
      detents,
    });
    // Lifting keeps the height, but never past the space above the keyboard.
    const limit = Math.max(0, room - inset);
    layoutRef.current = {
      ...layout,
      heights: {
        default: Math.min(layout.heights.default, limit),
        lg: Math.min(layout.heights.lg, limit),
      },
    };
    setShape({ expandable: layout.expandable, full: layout.full });
    if (dragRef.current?.mode !== "drag") rest(optionsRef.current.size);
  }, [popup, rest, setShape]);

  // Measure before the first paint, then once per frame after content,
  // viewport or keyboard changes.
  React.useLayoutEffect(() => {
    registerProgress();
    const container = containerRef.current;
    if (!popup || !container || !open) return;
    measure();
    const schedule = perFrame(measure);
    // Widening the sheet resizes every child; only height changes matter.
    const heights = new WeakMap<Element, number>();
    const resize = new ResizeObserver((entries) => {
      let changed = false;
      for (const entry of entries) {
        const height = entry.contentRect.height;
        if (heights.get(entry.target) !== height) changed = true;
        heights.set(entry.target, height);
      }
      if (changed) schedule();
    });
    const observe = () => {
      resize.disconnect();
      for (const child of Array.from(container.children)) resize.observe(child);
      if (popup.parentElement) resize.observe(popup.parentElement);
    };
    observe();
    const mutation = new MutationObserver(() => {
      observe();
      schedule();
    });
    mutation.observe(container, { childList: true });
    const events = new AbortController();
    const { signal } = events;
    window.visualViewport?.addEventListener("resize", schedule, { signal });
    window.visualViewport?.addEventListener("scroll", schedule, { signal });
    return () => {
      schedule.cancel();
      resize.disconnect();
      mutation.disconnect();
      events.abort();
    };
  }, [popup, open, measure]);

  // A new detent policy needs a fresh layout.
  // biome-ignore lint/correctness/useExhaustiveDependencies: the policy props trigger a measurement.
  React.useLayoutEffect(measure, [
    measure,
    options.detents,
    options.keyboard,
    options.footerMode,
  ]);

  // Settle at the size; the body scrolls only once expansion finishes.
  React.useLayoutEffect(() => {
    if (dragRef.current?.mode !== "drag") rest(size);
    if (size === "default" && containerRef.current)
      resetScroll(containerRef.current);
    setSettled(false);
    const timer = window.setTimeout(() => setSettled(true), settleDelay);
    return () => window.clearTimeout(timer);
  }, [size, rest]);

  // A new content key starts over at the default size, at the top.
  const contentKeyRef = React.useRef(contentKey);
  React.useEffect(() => {
    if (Object.is(contentKeyRef.current, contentKey)) return;
    contentKeyRef.current = contentKey;
    if (containerRef.current) resetScroll(containerRef.current);
    setSize("default");
  }, [contentKey, setSize]);

  const scrollable = !expandable || (size === "lg" && settled);
  React.useLayoutEffect(() => {
    scrollableRef.current = scrollable;
    applyScroll();
  }, [scrollable, applyScroll]);

  // Keep a focused field in view once the body can scroll.
  React.useEffect(() => {
    const active = document.activeElement;
    if (
      scrollable &&
      active instanceof HTMLElement &&
      active.matches(textField) &&
      containerRef.current?.contains(active)
    )
      active.scrollIntoView({ block: "nearest" });
  }, [scrollable]);

  // Drags: the header and grabber move the sheet with any pointer. Touch on
  // the body moves it while the body cannot scroll, or pulls it down from the
  // top of a scrolled body.
  React.useEffect(() => {
    const container = containerRef.current;
    if (!popup || !container) return;
    const tracker = createVelocityTracker();
    const events = new AbortController();
    const { signal } = events;
    let suppressClickUntil = 0;

    function begin(
      source: Drag["source"],
      x: number,
      y: number,
      pointerId: number | null,
    ) {
      const from = optionsRef.current.size;
      const extent = extentOf(from);
      dragRef.current = {
        source,
        pointerId,
        startX: x,
        startY: y,
        startExtent: extent,
        extent,
        from,
        mode: "pending",
      };
      tracker.reset();
      tracker.add(-y, performance.now());
    }
    // Vertical movement past the threshold drags the sheet, unless it starts
    // a scroll in a body that can scroll.
    function decide(drag: Drag, dx: number, dy: number): Drag["mode"] {
      const threshold = bottomSheetDefaults.dragThreshold;
      if (Math.abs(dy) < threshold || Math.abs(dy) <= Math.abs(dx))
        return Math.abs(dx) > threshold ? "native" : "pending";
      if (drag.source === "handle") return "drag";
      if (!container || container.dataset.scroll === "none") return "drag";
      const pullsFromTop = scrollElement(container).scrollTop <= 0 && dy > 0;
      return pullsFromTop ? "drag" : "native";
    }
    function move(drag: Drag, x: number, y: number, time: number) {
      tracker.add(-y, time);
      const dy = y - drag.startY;
      if (drag.mode === "pending") {
        drag.mode = decide(drag, x - drag.startX, dy);
        if (drag.mode !== "drag") return false;
        popup?.setAttribute("data-dragging", "");
        overlayRef.current?.setAttribute("data-dragging", "");
      }
      drag.extent = Math.min(
        drag.startExtent - dy,
        layoutRef.current.heights.lg,
      );
      paint(drag.extent);
      return true;
    }
    function target(drag: Drag, velocity: number) {
      const layout = layoutRef.current;
      // An upward swipe on the body at the default size expands even when it
      // is short.
      const swipedUp =
        drag.source === "body" &&
        drag.from === "default" &&
        layout.expandable &&
        drag.extent - layout.heights.default > 16 &&
        velocity > -bottomSheetDefaults.flickVelocity;
      if (swipedUp) return "lg";
      return resolveBottomSheetRelease({
        extent: drag.extent,
        velocity,
        layout,
        from: drag.from,
      });
    }
    function end(drag: Drag, time: number, cancelled: boolean) {
      dragRef.current = null;
      if (drag.mode !== "drag") return;
      popup?.removeAttribute("data-dragging");
      overlayRef.current?.removeAttribute("data-dragging");
      suppressClickUntil = performance.now() + 80;
      const next = target(drag, cancelled ? 0 : tracker.velocity(time));
      if (next !== "closed") {
        rest(next);
        if (next !== optionsRef.current.size) setSize(next);
        return;
      }
      optionsRef.current.close();
      // A parent that keeps the sheet open gets it back at its size.
      requestAnimationFrame(() => {
        if (optionsRef.current.isOpen()) rest(optionsRef.current.size);
      });
    }

    popup.addEventListener(
      "pointerdown",
      (event) => {
        const element = event.target as Element | null;
        if (event.button !== 0 || dragRef.current) return;
        if (!element?.closest(handle) || element.closest(textField)) return;
        begin("handle", event.clientX, event.clientY, event.pointerId);
      },
      { signal },
    );
    popup.addEventListener(
      "pointermove",
      (event) => {
        const drag = dragRef.current;
        if (drag?.pointerId !== event.pointerId || drag.mode === "native")
          return;
        const pending = drag.mode === "pending";
        const dragging = move(
          drag,
          event.clientX,
          event.clientY,
          event.timeStamp,
        );
        if (dragging && pending) capture(popup, event.pointerId);
      },
      { signal },
    );
    const release = (event: PointerEvent) => {
      const drag = dragRef.current;
      if (drag?.pointerId === event.pointerId)
        end(drag, event.timeStamp, event.type === "pointercancel");
    };
    popup.addEventListener("pointerup", release, { signal });
    popup.addEventListener("pointercancel", release, { signal });
    // A finished drag must not also press what it started on.
    popup.addEventListener(
      "click",
      (event) => {
        if (performance.now() > suppressClickUntil) return;
        event.preventDefault();
        event.stopPropagation();
      },
      { capture: true, signal },
    );
    container.addEventListener(
      "touchstart",
      (event) => {
        const touch = event.touches[0];
        const element = event.target as Element | null;
        if (event.touches.length !== 1 || !touch || dragRef.current) return;
        if (!element || element.closest(handle) || element.closest(ownGesture))
          return;
        begin("body", touch.clientX, touch.clientY, null);
      },
      { passive: true, signal },
    );
    container.addEventListener(
      "touchmove",
      (event) => {
        const drag = dragRef.current;
        const touch = event.touches[0];
        if (drag?.source !== "body" || drag.mode === "native" || !touch) return;
        const dragging = move(
          drag,
          touch.clientX,
          touch.clientY,
          event.timeStamp,
        );
        if (dragging && event.cancelable) event.preventDefault();
      },
      { passive: false, signal },
    );
    const touchEnd = (event: TouchEvent) => {
      const drag = dragRef.current;
      if (drag?.source === "body")
        end(drag, event.timeStamp, event.type === "touchcancel");
    };
    container.addEventListener("touchend", touchEnd, { signal });
    container.addEventListener("touchcancel", touchEnd, { signal });
    return () => events.abort();
  }, [popup, paint, rest, extentOf, setSize]);

  // Wheel, focus and header state while the body scrolls.
  React.useEffect(() => {
    const container = containerRef.current;
    if (!popup || !container) return;
    const events = new AbortController();
    const { signal } = events;
    let wheelUntil = 0;
    const canExpand = () =>
      layoutRef.current.expandable && optionsRef.current.size === "default";

    // An expandable sheet at the default size expands on the first scroll down
    // and absorbs the rest of that wheel gesture.
    container.addEventListener(
      "wheel",
      (event) => {
        const now = performance.now();
        const expands = canExpand() && event.deltaY > 0;
        if (now >= wheelUntil && !expands) return;
        wheelUntil = now + 250;
        if (event.cancelable) event.preventDefault();
        if (expands) setSize("lg");
      },
      { passive: false, signal },
    );
    container.addEventListener(
      "focusin",
      (event) => {
        const element = event.target as Element | null;
        if (
          optionsRef.current.expandOnInputFocus &&
          canExpand() &&
          element?.matches(textField)
        )
          setSize("lg");
      },
      { signal },
    );
    const updateHeader = perFrame(() => {
      const header = part(container, "header");
      if (header?.dataset.collapseOnScroll !== "true") return;
      const scroller = scrollElement(container);
      const top = scroller.scrollTop;
      const collapsed = header.hasAttribute("data-collapsed");
      // Hysteresis keeps a short scroll range from toggling back and forth.
      const range = scroller.scrollHeight - scroller.clientHeight;
      if (!collapsed && top > 24 && range > 48) {
        header.dataset.naturalHeight = `${header.offsetHeight}`;
        header.setAttribute("data-collapsed", "");
      }
      if (collapsed && top < 4) header.removeAttribute("data-collapsed");
    });
    // Scroll events do not bubble, so listen while they pass down to the body.
    container.addEventListener("scroll", updateHeader, {
      capture: true,
      passive: true,
      signal,
    });
    return () => {
      updateHeader.cancel();
      events.abort();
    };
  }, [popup, setSize]);

  return { popupRef: setPopup, containerRef, overlayRef, probeRef };
}

"use client";

import { useEffect, useRef, useState } from "react";

type ClipboardStatus = "idle" | "pending" | "copied" | "error";
type ClipboardLabels = {
  copy?: string;
  pending?: string;
  copied?: string;
  failed?: string;
};
type ClipboardOptions = {
  disabled?: boolean;
  resetDelay?: number;
  onCopy?: (value: string) => void;
  onCopyError?: (error: Error) => void;
};
type ClipboardControllerOptions = Omit<ClipboardOptions, "disabled"> & {
  writeText: (value: string) => Promise<void>;
  onStatusChange: (status: ClipboardStatus) => void;
};

// The controller owns each async attempt, so late results never update a newer
// value, a second attempt, or an unmounted component.
function createClipboardController(options: ClipboardControllerOptions) {
  let active = true;
  let pending = false;
  let attempt = 0;
  let copiedValue: string | undefined;
  let timer: ReturnType<typeof setTimeout> | undefined;
  const clear = () => {
    if (timer !== undefined) clearTimeout(timer);
    timer = undefined;
  };
  const reset = () => {
    attempt++;
    pending = false;
    copiedValue = undefined;
    clear();
    if (active) options.onStatusChange("idle");
  };
  return {
    activate() {
      active = true;
    },
    reset,
    synchronize(value: string) {
      // An uncontrolled input can synchronize after copying its live DOM value.
      if (value !== copiedValue) reset();
    },
    dispose() {
      active = false;
      attempt++;
      pending = false;
      copiedValue = undefined;
      clear();
    },
    async copy(value: string): Promise<boolean> {
      if (!active || pending) return false;
      const current = ++attempt;
      copiedValue = value;
      pending = true;
      clear();
      options.onStatusChange("pending");
      try {
        await options.writeText(value);
      } catch (reason) {
        if (!active || current !== attempt) return false;
        pending = false;
        const error =
          reason instanceof Error ? reason : new Error(String(reason));
        options.onStatusChange("error");
        options.onCopyError?.(error);
        return false;
      }
      if (!active || current !== attempt) return false;
      pending = false;
      options.onStatusChange("copied");
      const delay = options.resetDelay ?? 1500;
      timer = setTimeout(
        () => {
          timer = undefined;
          if (active && current === attempt) options.onStatusChange("idle");
        },
        Number.isFinite(delay) ? Math.max(0, delay) : 1500,
      );
      options.onCopy?.(value);
      return true;
    },
  };
}

function useClipboard(value: string, options: ClipboardOptions = {}) {
  const [status, setStatus] = useState<ClipboardStatus>("idle");
  const optionsRef = useRef(options);
  optionsRef.current = options;
  const [controller] = useState(() =>
    createClipboardController({
      writeText: async (text) => {
        if (
          typeof navigator === "undefined" ||
          !navigator.clipboard?.writeText
        ) {
          throw new Error(
            "Clipboard access is unavailable. Select and copy the text manually.",
          );
        }
        await navigator.clipboard.writeText(text);
      },
      onStatusChange: setStatus,
      onCopy: (text) => optionsRef.current.onCopy?.(text),
      onCopyError: (error) => optionsRef.current.onCopyError?.(error),
      get resetDelay() {
        return optionsRef.current.resetDelay;
      },
    }),
  );
  useEffect(() => {
    controller.activate();
    return () => controller.dispose();
  }, [controller]);
  useEffect(() => {
    if (options.disabled) controller.reset();
    else controller.synchronize(value);
  }, [controller, value, options.disabled]);
  return {
    status,
    copy: (text = value) =>
      options.disabled ? Promise.resolve(false) : controller.copy(text),
    reset: controller.reset,
  };
}

export type { ClipboardLabels, ClipboardOptions, ClipboardStatus };
export { createClipboardController, useClipboard };

"use client";

import { useCallback, useEffect, useState } from "react";

let nextEditorModelId = 0;

export function useEditorValue({
  value,
  defaultValue = "",
  onChange,
  disabled,
}: Readonly<{
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  disabled?: boolean;
}>) {
  const [localValue, setLocalValue] = useState(value ?? defaultValue);

  useEffect(() => {
    if (value !== undefined) setLocalValue(value);
  }, [value]);

  const handleChange = useCallback(
    (nextValue: string) => {
      if (disabled) return;
      if (value === undefined) setLocalValue(nextValue);
      onChange?.(nextValue);
    },
    [disabled, onChange, value],
  );

  return { resolvedValue: value ?? localValue, handleChange };
}

export function useEditorModelPath(language: string) {
  // Monaco keeps models process-wide by URI, including across separate React roots.
  // The path is only rendered after mount, so a client-local ID is sufficient.
  const [instanceId] = useState(() => ++nextEditorModelId);
  let extension = language;
  if (language === "typescript") extension = "ts";
  else if (language === "javascript") extension = "jsx";
  return `file:///editor-${instanceId}/index.${extension}`;
}

"use client";
import {
  type RefObject,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";

const focusSelector =
  'button:not(:disabled), a[href], input:not(:disabled), textarea:not(:disabled), select:not(:disabled), [tabindex], [contenteditable="true"], iframe';

function frameDocument(frame: HTMLIFrameElement) {
  try {
    return frame.contentDocument;
  } catch {
    return null;
  }
}
function isFocusable(node: HTMLElement) {
  if (node.hasAttribute("tabindex") && node.tabIndex < 0) return false;
  for (
    let current: HTMLElement | null = node;
    current;
    current = current.parentElement
  ) {
    if (current.hidden || current.hasAttribute("inert")) return false;
    const style = current.ownerDocument.defaultView?.getComputedStyle(current);
    if (style?.display === "none" || style?.visibility === "hidden")
      return false;
  }
  return true;
}
function focusableNodes(
  container: HTMLElement | Document,
  visited = new Set<Document>(),
): HTMLElement[] {
  const owner = container.ownerDocument ?? (container as Document);
  if (visited.has(owner)) return [];
  visited.add(owner);
  return Array.from(
    container.querySelectorAll<HTMLElement>(focusSelector),
  ).flatMap((node) => {
    if (!isFocusable(node)) return [];
    if (node.tagName !== "IFRAME") return [node];
    const child = frameDocument(node as HTMLIFrameElement);
    const inside = child ? focusableNodes(child, visited) : [];
    return inside.length ? inside : [node];
  });
}
function deepActiveElement(owner: Document): HTMLElement | null {
  let active = owner.activeElement as HTMLElement | null;
  const seen = new Set<Element>();
  while (active?.tagName === "IFRAME" && !seen.has(active)) {
    seen.add(active);
    const child = frameDocument(active as HTMLIFrameElement);
    const next = child?.activeElement;
    if (!next || next === child?.body || next === child?.documentElement) break;
    active = next as HTMLElement;
  }
  return active;
}

function bindFullscreenKeyboard(
  element: HTMLElement,
  exit: () => void,
  isTop: () => boolean,
) {
  const owner = element.ownerDocument;
  const documents = new Map<
    Document,
    { observer: MutationObserver; target: Node }
  >();
  const frames = new Map<HTMLIFrameElement, () => void>();
  let frame = 0;
  let disposed = false;
  const onKeyDown = (event: KeyboardEvent) => {
    if (event.defaultPrevented || !isTop()) return;
    // Nested popup portals manage their own focus and Escape handling.
    const target = event.target as Element | null;
    const popup = target?.closest?.(
      '[data-base-ui-portal], [role="dialog"], [role="alertdialog"]',
    );
    if (popup && !popup.contains(element)) return;
    const eventDocument = event.currentTarget as Document;
    if (
      eventDocument !== owner &&
      fixedOverlays.get(eventDocument)?.entries.length
    )
      return;
    if (event.key === "Escape") {
      event.preventDefault();
      exit();
      return;
    }
    if (event.key !== "Tab") return;
    const nodes = focusableNodes(element);
    const first = nodes[0];
    const last = nodes.at(-1);
    const active = deepActiveElement(owner);
    if (!first) {
      event.preventDefault();
      return;
    }
    if (
      event.shiftKey &&
      (active === first || !nodes.includes(active as HTMLElement))
    ) {
      event.preventDefault();
      last?.focus();
    } else if (
      !event.shiftKey &&
      (active === last || !nodes.includes(active as HTMLElement))
    ) {
      event.preventDefault();
      first.focus();
    }
  };
  const schedule = () => {
    if (disposed || frame) return;
    frame = requestAnimationFrame(() => {
      frame = 0;
      refresh();
    });
  };
  function refresh() {
    if (disposed) return;
    const nextDocuments = new Map<Document, Node>([[owner, element]]);
    const nextFrames = new Set<HTMLIFrameElement>();
    const collect = (container: HTMLElement | Document) => {
      for (const nested of container.querySelectorAll<HTMLIFrameElement>(
        "iframe",
      )) {
        nextFrames.add(nested);
        const child = frameDocument(nested);
        if (!child?.documentElement || nextDocuments.has(child)) continue;
        nextDocuments.set(child, child.documentElement);
        collect(child);
      }
    };
    collect(element);
    for (const [current, binding] of documents) {
      if (nextDocuments.has(current)) continue;
      current.removeEventListener("keydown", onKeyDown);
      binding.observer.disconnect();
      documents.delete(current);
    }
    for (const [current, target] of nextDocuments) {
      if (documents.has(current)) continue;
      const observer = new MutationObserver(schedule);
      observer.observe(target, { childList: true, subtree: true });
      current.addEventListener("keydown", onKeyDown);
      documents.set(current, { observer, target });
    }
    for (const [current, loaded] of frames) {
      if (nextFrames.has(current)) continue;
      current.removeEventListener("load", loaded);
      frames.delete(current);
    }
    for (const current of nextFrames) {
      if (frames.has(current)) continue;
      const loaded = () => refresh();
      current.addEventListener("load", loaded);
      frames.set(current, loaded);
    }
  }
  refresh();
  return () => {
    disposed = true;
    cancelAnimationFrame(frame);
    for (const [current, binding] of documents) {
      current.removeEventListener("keydown", onKeyDown);
      binding.observer.disconnect();
    }
    for (const [current, loaded] of frames)
      current.removeEventListener("load", loaded);
    documents.clear();
    frames.clear();
  };
}

type FixedOverlay = { element: HTMLElement; previousFocus: HTMLElement | null };
type FixedOverlayStack = {
  entries: FixedOverlay[];
  overflow: string;
  overflowPriority: string;
  returnFocus: HTMLElement | null;
};
const fixedOverlays = new WeakMap<Document, FixedOverlayStack>();

function acquireFixedOverlay(element: HTMLElement, exit: () => void) {
  const owner = element.ownerDocument;
  let stack = fixedOverlays.get(owner);
  const previousFocus = deepActiveElement(owner);
  if (!stack) {
    stack = {
      entries: [],
      overflow: owner.body.style.getPropertyValue("overflow"),
      overflowPriority: owner.body.style.getPropertyPriority("overflow"),
      returnFocus: previousFocus,
    };
    fixedOverlays.set(owner, stack);
    owner.body.style.setProperty("overflow", "hidden");
  }
  const entry: FixedOverlay = { element, previousFocus };
  stack.entries.push(entry);
  const activeStack = stack;
  const stop = bindFullscreenKeyboard(
    element,
    exit,
    () => activeStack.entries.at(-1) === entry,
  );
  focusableNodes(element)[0]?.focus();
  let released = false;
  return () => {
    if (released) return;
    released = true;
    const wasTop = activeStack.entries.at(-1) === entry;
    stop();
    const index = activeStack.entries.indexOf(entry);
    if (index >= 0) activeStack.entries.splice(index, 1);
    const next = activeStack.entries.at(-1);
    if (!next) {
      fixedOverlays.delete(owner);
      if (activeStack.overflow)
        owner.body.style.setProperty(
          "overflow",
          activeStack.overflow,
          activeStack.overflowPriority,
        );
      else owner.body.style.removeProperty("overflow");
      if (activeStack.returnFocus?.isConnected) activeStack.returnFocus.focus();
    } else if (wasTop) {
      const nodes = focusableNodes(next.element);
      if (entry.previousFocus && nodes.includes(entry.previousFocus))
        entry.previousFocus.focus();
      else nodes[0]?.focus();
    }
  };
}

/** Manages controlled or uncontrolled fixed and browser fullscreen state. */
export function useFullscreen({
  fullscreen: controlledFullscreen,
  defaultFullscreen = false,
  onFullscreenChange,
  mode = "fixed",
  ref,
}: {
  fullscreen?: boolean;
  defaultFullscreen?: boolean;
  onFullscreenChange?: (fullscreen: boolean) => void;
  mode?: "fixed" | "screen";
  ref?: RefObject<HTMLDivElement | null>;
} = {}) {
  const internalRef = useRef<HTMLDivElement>(null);
  const targetRef = ref ?? internalRef;
  const wasOwnFullscreen = useRef(false);
  const [uncontrolledFullscreen, setUncontrolledFullscreen] =
    useState(defaultFullscreen);
  const fullscreen = controlledFullscreen ?? uncontrolledFullscreen;

  const setFullscreen = useCallback(
    (nextFullscreen: boolean) => {
      if (controlledFullscreen === undefined)
        setUncontrolledFullscreen(nextFullscreen);
      onFullscreenChange?.(nextFullscreen);
    },
    [controlledFullscreen, onFullscreenChange],
  );

  const latestSetFullscreen = useRef(setFullscreen);
  useEffect(() => {
    latestSetFullscreen.current = setFullscreen;
  }, [setFullscreen]);

  useEffect(() => {
    if (mode !== "screen") return;

    function handleFullscreenChange() {
      const isOwnFullscreen = Boolean(
        targetRef.current && document.fullscreenElement === targetRef.current,
      );
      if (wasOwnFullscreen.current && !isOwnFullscreen && fullscreen)
        setFullscreen(false);
      wasOwnFullscreen.current = isOwnFullscreen;
    }

    document.addEventListener("fullscreenchange", handleFullscreenChange);
    return () =>
      document.removeEventListener("fullscreenchange", handleFullscreenChange);
  }, [fullscreen, mode, setFullscreen, targetRef]);

  useEffect(() => {
    if (mode !== "screen") return;

    const element = targetRef.current;
    if (!element) return;

    if (fullscreen) {
      if (document.fullscreenElement !== element) {
        if (!element.requestFullscreen) {
          setFullscreen(false);
          return;
        }
        element.requestFullscreen().catch(() => setFullscreen(false));
      }
      return;
    }

    if (document.fullscreenElement === element) {
      document.exitFullscreen?.()?.catch(() => setFullscreen(true));
    }
  }, [fullscreen, mode, setFullscreen, targetRef]);

  useEffect(() => {
    if (mode !== "fixed" || !fullscreen) return;
    const element = targetRef.current;
    if (!element) return;
    return acquireFixedOverlay(element, () =>
      latestSetFullscreen.current(false),
    );
  }, [fullscreen, mode, targetRef]);

  return {
    ref: targetRef,
    fullscreen,
    setFullscreen,
  };
}

import * as React from "react";

const MOBILE_BREAKPOINT = 768;

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(
    undefined,
  );

  React.useLayoutEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`);
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    };
    mql.addEventListener("change", onChange);
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    return () => mql.removeEventListener("change", onChange);
  }, []);

  return !!isMobile;
}

"use client";

import { useSyncExternalStore } from "react";

let media: MediaQueryList | undefined;
function getMedia() {
  if (typeof window === "undefined" || !window.matchMedia) return undefined;
  media ??= window.matchMedia("(prefers-reduced-motion: reduce)");
  return media;
}
function subscribe(listener: () => void) {
  const query = getMedia();
  query?.addEventListener("change", listener);
  return () => query?.removeEventListener("change", listener);
}
function getSnapshot() {
  return getMedia()?.matches ?? true;
}
function getServerSnapshot() {
  return true;
}

function useReducedMotion() {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

export { useReducedMotion };

import {
  type RefObject,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import type { ThemedToken } from "@/lib/viewer/shiki";

import { useShikiThemes } from "@/lib/viewer/shiki-context";

const EMPTY_LINES: ThemedToken[][] = [];

type HighlightResult = Readonly<{
  key: string;
  lines: ThemedToken[][];
  failed: boolean;
}>;

export function useHighlightedLines(
  code: string,
  lang: string,
  theme: "light" | "dark",
) {
  const themes = useShikiThemes();
  const key = `${lang}\u0000${theme}\u0000${themes.light}\u0000${themes.dark}\u0000${code}`;
  const [result, setResult] = useState<HighlightResult | null>(null);

  useEffect(() => {
    if (!code) return;
    let active = true;
    import("@/lib/viewer/shiki")
      .then(({ codeToViewerTokens }) =>
        codeToViewerTokens(code, lang, theme, themes),
      )
      .then((lines) => {
        if (active) setResult({ key, lines, failed: false });
      })
      .catch(() => {
        if (active) setResult({ key, lines: [], failed: true });
      });
    return () => {
      active = false;
    };
  }, [code, key, lang, theme, themes]);

  const current = result?.key === key ? result : null;
  return {
    lines: current?.lines ?? EMPTY_LINES,
    failed: current?.failed ?? false,
    loading: Boolean(code) && !current,
  };
}

export function useStreamingScroll(
  viewportRef: RefObject<HTMLDivElement | null>,
  content: string,
  streaming: boolean,
) {
  const followRef = useRef(true);
  const lastScrollTop = useRef(0);
  const wasStreaming = useRef(streaming);
  const updateFollow = useCallback((viewport: HTMLDivElement) => {
    const top = viewport.scrollTop;
    // Scroll notifications may arrive after new content changes the bottom.
    // An unchanged position is not a reader choosing to scroll away.
    if (top === lastScrollTop.current) return;
    lastScrollTop.current = top;
    followRef.current =
      viewport.scrollHeight - viewport.clientHeight - top <= 32;
  }, []);
  useEffect(() => {
    const viewport = viewportRef.current;
    if (!viewport) return;
    if (streaming) followRef.current = true;
    lastScrollTop.current = viewport.scrollTop;
    const onScroll = () => updateFollow(viewport);
    viewport.addEventListener("scroll", onScroll, { passive: true });
    return () => viewport.removeEventListener("scroll", onScroll);
  }, [streaming, viewportRef, updateFollow]);
  useEffect(() => {
    const viewport = viewportRef.current;
    const completing = wasStreaming.current && !streaming;
    wasStreaming.current = streaming;
    if (
      (!streaming && !completing) ||
      !content ||
      !viewport ||
      !followRef.current
    )
      return;
    const frame = requestAnimationFrame(() => {
      updateFollow(viewport);
      if (!followRef.current || viewport.scrollHeight <= viewport.clientHeight)
        return;
      viewport.scrollTo({
        top: viewport.scrollHeight,
        behavior: "instant",
      });
      lastScrollTop.current = viewport.scrollTop;
    });
    return () => cancelAnimationFrame(frame);
  }, [content, streaming, viewportRef, updateFollow]);
}

"use client";

import { type RefObject, useEffect, useState } from "react";

function useViewerTheme(ref?: RefObject<HTMLElement | null>) {
  const [resolvedTheme, setTheme] = useState<"light" | "dark">("light");
  useEffect(() => {
    const resolve = () =>
      setTheme(
        (ref?.current ?? document.documentElement).closest(".dark")
          ? "dark"
          : "light",
      );
    const observer = new MutationObserver(resolve);
    for (
      let node: HTMLElement | null = ref?.current ?? document.documentElement;
      node;
      node = node.parentElement
    )
      observer.observe(node, { attributes: true, attributeFilter: ["class"] });
    resolve();
    return () => observer.disconnect();
  }, [ref]);
  return { resolvedTheme };
}

export { useViewerTheme };

/** The sheet's detents: `"default"` rests at about half height, `"lg"` fills it. */
export type BottomSheetSize = "default" | "lg";

/**
 * `"auto"` adds the `"lg"` size only when content outgrows `"default"`,
 * `"always"` keeps both, and `false` sizes a single detent to content.
 */
export type BottomSheetDetents = "auto" | "always" | false;

export type BottomSheetLayout = {
  /** Visible height at each size; both are equal for a single detent. */
  heights: Record<BottomSheetSize, number>;
  /** The sheet can grow from `"default"` to `"lg"`. */
  expandable: boolean;
  /** The sheet fills the available height, so it reads as expanded. */
  full: boolean;
};

export const bottomSheetDefaults = {
  /** The default size takes at most half the available height, as on iOS. */
  defaultRatio: 0.5,
  /** Body space the default size must keep beside its header and footer. */
  minimumBody: 80,
  /** Movement before a press becomes a drag. */
  dragThreshold: 6,
  /** Release velocity, in px/ms, that moves one size in its direction. */
  flickVelocity: 0.3,
  /** Samples older than this, in ms, no longer count toward velocity. */
  velocityWindow: 100,
} as const;

/**
 * Resolves the height of each size from the space above the keyboard and
 * below the top safe area, the content's natural height and its header and
 * footer.
 */
export function bottomSheetLayout({
  available,
  natural,
  chrome,
  detents,
  defaultRatio = bottomSheetDefaults.defaultRatio,
  minimumBody = bottomSheetDefaults.minimumBody,
}: {
  available: number;
  natural: number;
  /** Header and footer height, which the default size must fit. */
  chrome: number;
  detents: BottomSheetDetents;
  defaultRatio?: number;
  minimumBody?: number;
}): BottomSheetLayout {
  const maximum = Math.max(0, available);
  const content = Math.max(0, natural);
  const single = (height: number): BottomSheetLayout => ({
    heights: { default: height, lg: height },
    expandable: false,
    full: height >= maximum - 1,
  });
  if (detents === false) return single(Math.min(content, maximum));
  const limit = maximum * defaultRatio;
  if (content > limit && limit < chrome + minimumBody)
    return single(Math.min(content, maximum));
  if (detents === "auto" && content <= limit) return single(content);
  const base = Math.min(content, limit);
  if (maximum - base <= 1) return single(maximum);
  return {
    heights: { default: base, lg: maximum },
    expandable: true,
    full: false,
  };
}

/**
 * Places a visible height: above the default size the sheet grows toward
 * `"lg"`, below it the sheet keeps its height and slides down toward closing.
 */
export function bottomSheetFrame(extent: number, layout: BottomSheetLayout) {
  const { heights, full } = layout;
  const visible = Math.min(extent, heights.lg);
  if (visible < heights.default)
    return {
      height: heights.default,
      offset: heights.default - Math.max(0, visible),
      progress: full ? 1 : 0,
    };
  return {
    height: visible,
    offset: 0,
    progress: frameProgress(visible, layout),
  };
}

/** 0 at the default size and 1 at `"lg"`; a full sheet stays 1. */
function frameProgress(visible: number, layout: BottomSheetLayout) {
  const { heights, expandable, full } = layout;
  if (full) return 1;
  const range = heights.lg - heights.default;
  if (!expandable || range <= 0) return 0;
  return (visible - heights.default) / range;
}

/** Distance below the default size at which a slow release closes. */
function bottomSheetCloseDistance(height: number) {
  return Math.min(Math.max(height * 0.35, 48), 180);
}

/**
 * Chooses where a drag settles. A flick moves one size in its direction;
 * otherwise the nearest size wins. A drag that began at `"lg"` cannot close
 * unless it was pulled below the default size first.
 */
export function resolveBottomSheetRelease({
  extent,
  velocity,
  layout,
  from,
  flickVelocity = bottomSheetDefaults.flickVelocity,
}: {
  /** Visible height at release. */
  extent: number;
  /** Upward velocity in px/ms; negative values move down. */
  velocity: number;
  layout: BottomSheetLayout;
  from: BottomSheetSize;
  flickVelocity?: number;
}): BottomSheetSize | "closed" {
  const { heights, expandable } = layout;
  const base = heights.default;
  const below = extent < base - 1;
  if (velocity >= flickVelocity) {
    if (expandable && extent >= base - 1) return "lg";
    return "default";
  }
  if (velocity <= -flickVelocity) {
    if (expandable && extent > base + 1) return "default";
    if (from === "lg" && expandable && !below) return "default";
    return below || extent <= base ? "closed" : "default";
  }
  if (below)
    return base - extent > bottomSheetCloseDistance(base)
      ? "closed"
      : "default";
  if (!expandable) return "default";
  return extent - base > (heights.lg - base) / 2 ? "lg" : "default";
}

/** Tracks recent pointer positions so a pause before release drops momentum. */
export function createVelocityTracker(
  window: number = bottomSheetDefaults.velocityWindow,
) {
  let samples: { time: number; position: number }[] = [];
  return {
    reset() {
      samples = [];
    },
    add(position: number, time: number) {
      samples.push({ position, time });
      while (samples.length > 2 && time - (samples[0]?.time ?? time) > window)
        samples.shift();
    },
    /** Velocity in px/ms along the tracked axis at `time`. */
    velocity(time: number) {
      const recent = samples.filter((sample) => time - sample.time <= window);
      const first = recent[0];
      const last = recent[recent.length - 1];
      if (!first || !last || last.time - first.time < 8) return 0;
      return (last.position - first.position) / (last.time - first.time);
    },
  };
}

export interface HSVColor {
  h: number;
  s: number;
  v: number;
  a: number;
}

export function clampColor(value: number, min = 0, max = 1) {
  if (!Number.isFinite(value)) return min;
  return Math.min(max, Math.max(min, value));
}

export function parseHexColor(value: string): HSVColor | null {
  let hex = value.trim().replace(/^#/, "");
  if (!/^(?:[\da-f]{3}|[\da-f]{4}|[\da-f]{6}|[\da-f]{8})$/i.test(hex))
    return null;
  if (hex.length <= 4) hex = [...hex].map((digit) => digit + digit).join("");
  const r = Number.parseInt(hex.slice(0, 2), 16) / 255;
  const g = Number.parseInt(hex.slice(2, 4), 16) / 255;
  const b = Number.parseInt(hex.slice(4, 6), 16) / 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;
  let h = 0;
  if (delta) {
    if (max === r) h = ((g - b) / delta) % 6;
    else if (max === g) h = (b - r) / delta + 2;
    else h = (r - g) / delta + 4;
    h = (h * 60 + 360) % 360;
  }
  let a = 1;
  if (hex.length === 8) a = Number.parseInt(hex.slice(6, 8), 16) / 255;
  return { h, s: max === 0 ? 0 : delta / max, v: max, a };
}

export function colorToRGB(color: HSVColor) {
  const h = (((color.h % 360) + 360) % 360) / 60;
  const s = clampColor(color.s);
  const v = clampColor(color.v);
  const chroma = v * s;
  const x = chroma * (1 - Math.abs((h % 2) - 1));
  const offset = v - chroma;
  const sectors = [
    [chroma, x, 0],
    [x, chroma, 0],
    [0, chroma, x],
    [0, x, chroma],
    [x, 0, chroma],
    [chroma, 0, x],
  ];
  return (sectors[Math.floor(h)] ?? sectors[0] ?? [0, 0, 0]).map((channel) =>
    Math.round((channel + offset) * 255),
  ) as [number, number, number];
}

export function colorToHex(color: HSVColor, alpha = false) {
  const channels = colorToRGB(color);
  if (alpha) channels.push(Math.round(clampColor(color.a) * 255));
  return `#${channels
    .map((channel) => channel.toString(16).padStart(2, "0"))
    .join("")
    .toUpperCase()}`;
}

export function colorToCSS(color: HSVColor) {
  return `rgba(${colorToRGB(color).join(", ")}, ${clampColor(color.a)})`;
}

export type ColorFormat = "hex" | "rgb" | "hsl" | "hsb" | "oklch";

export function formatColor(
  color: HSVColor,
  format: ColorFormat,
  alpha = false,
) {
  if (format === "hex") return colorToHex(color, alpha);
  const opacity = Math.round(clampColor(color.a) * 10000) / 10000;
  const suffix = alpha ? ` / ${opacity}` : "";
  if (format === "oklch") {
    const { l, c, h } = colorToOKLCH(color);
    return `oklch(${Number((l * 100).toFixed(5))}% ${Number(c.toFixed(7))} ${Number(h.toFixed(5))}${suffix})`;
  }
  if (format === "rgb") return `rgb(${colorToRGB(color).join(" ")}${suffix})`;
  const hue = Math.round(color.h);
  if (format === "hsb")
    return `hsb(${hue} ${Math.round(color.s * 100)}% ${Math.round(color.v * 100)}%${suffix})`;
  const lightness = color.v * (1 - color.s / 2);
  let saturation = 0;
  if (lightness > 0 && lightness < 1)
    saturation = (color.v - lightness) / Math.min(lightness, 1 - lightness);
  return `hsl(${hue} ${Math.round(saturation * 100)}% ${Math.round(lightness * 100)}%${suffix})`;
}

export function parseColor(
  value: string,
  format: ColorFormat,
): HSVColor | null {
  if (format === "hex") return parseHexColor(value);
  if (format === "oklch") return parseOKLCH(value);
  const match = value
    .trim()
    .match(
      /^(rgb|hsl|hsb)\(\s*([+-]?[\d.]+)[ ,]+([+-]?[\d.]+)(%)?[ ,]+([+-]?[\d.]+)(%)?(?:\s*[/,]\s*([\d.]+)(%)?)?\s*\)$/i,
    );
  if (!match || match[1]?.toLowerCase() !== format) return null;
  const first = Number(match[2]);
  const second = Number(match[3]);
  const third = Number(match[5]);
  let a = 1;
  if (match[7]) a = Number(match[7]) / (match[8] ? 100 : 1);
  if (![first, second, third, a].every(Number.isFinite) || a < 0 || a > 1)
    return null;
  if (format === "rgb") {
    if (
      match[4] ||
      match[6] ||
      [first, second, third].some((channel) => channel < 0 || channel > 255)
    )
      return null;
    const hex = [first, second, third]
      .map((channel) => Math.round(channel).toString(16).padStart(2, "0"))
      .join("");
    const color = parseHexColor(hex);
    return color ? { ...color, a } : null;
  }
  if (
    !match[4] ||
    !match[6] ||
    second < 0 ||
    second > 100 ||
    third < 0 ||
    third > 100
  )
    return null;
  const h = ((first % 360) + 360) % 360;
  if (format === "hsb") return { h, s: second / 100, v: third / 100, a };
  const lightness = third / 100;
  const v = lightness + (second / 100) * Math.min(lightness, 1 - lightness);
  return { h, s: v === 0 ? 0 : 2 * (1 - lightness / v), v, a };
}

export interface OKLCHColor {
  l: number;
  c: number;
  h: number;
  a: number;
}

export function colorToOKLCH(color: HSVColor): OKLCHColor {
  const [r, g, b] = colorToRGB(color).map((channel) => {
    const value = channel / 255;
    return value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4;
  });
  const red = r ?? 0;
  const green = g ?? 0;
  const blue = b ?? 0;
  const l = Math.cbrt(
    0.4122214708 * red + 0.5363325363 * green + 0.0514459929 * blue,
  );
  const m = Math.cbrt(
    0.2119034982 * red + 0.6806995451 * green + 0.1073969566 * blue,
  );
  const s = Math.cbrt(
    0.0883024619 * red + 0.2817188376 * green + 0.6299787005 * blue,
  );
  const lightness = 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s;
  const a = 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s;
  const bAxis = 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s;
  const chroma = Math.hypot(a, bAxis);
  const achromatic = chroma < 1e-7;
  return {
    l: lightness,
    c: achromatic ? 0 : chroma,
    h: achromatic ? 0 : ((Math.atan2(bAxis, a) * 180) / Math.PI + 360) % 360,
    a: clampColor(color.a),
  };
}

function oklchLinearRGB(lightness: number, chroma: number, hue: number) {
  const angle = (hue * Math.PI) / 180;
  const a = chroma * Math.cos(angle);
  const b = chroma * Math.sin(angle);
  const l = (lightness + 0.3963377774 * a + 0.2158037573 * b) ** 3;
  const m = (lightness - 0.1055613458 * a - 0.0638541728 * b) ** 3;
  const s = (lightness - 0.0894841775 * a - 1.291485548 * b) ** 3;
  return [
    4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s,
  ];
}

export function oklchToColor(color: OKLCHColor): HSVColor {
  const lightness = clampColor(color.l);
  const hue = ((color.h % 360) + 360) % 360;
  // Chroma reduction preserves lightness and hue while fitting the sRGB gamut.
  let chroma = clampColor(color.c, 0, 4);
  let channels = oklchLinearRGB(lightness, chroma, hue);
  const inGamut = (values: number[]) =>
    values.every(
      (channel) =>
        Number.isFinite(channel) && channel >= -1e-7 && channel <= 1 + 1e-7,
    );
  if (!inGamut(channels)) {
    let low = 0;
    let high = chroma;
    for (let iteration = 0; iteration < 32; iteration++) {
      const middle = (low + high) / 2;
      if (inGamut(oklchLinearRGB(lightness, middle, hue))) low = middle;
      else high = middle;
    }
    chroma = low;
    channels = oklchLinearRGB(lightness, chroma, hue);
  }
  const hex = channels
    .map((channel) => {
      const linear = clampColor(channel);
      const value =
        linear <= 0.0031308
          ? linear * 12.92
          : 1.055 * linear ** (1 / 2.4) - 0.055;
      return Math.round(clampColor(value) * 255)
        .toString(16)
        .padStart(2, "0");
    })
    .join("");
  return {
    ...(parseHexColor(hex) ?? { h: 0, s: 0, v: lightness, a: 1 }),
