}

function cssVar(element: HTMLElement, name: string) {
  const raw = getComputedStyle(element).getPropertyValue(name).trim();
  if (!raw) return "";
  const canvas = document.createElement("canvas");
  canvas.width = canvas.height = 1;
  const ctx = canvas.getContext("2d");
  if (!ctx) return "";
  ctx.fillStyle = raw;
  ctx.fillRect(0, 0, 1, 1);
  const [r, g, b, a] = ctx.getImageData(0, 0, 1, 1).data;
  const hex = (v: number) => v.toString(16).padStart(2, "0");
  return `#${hex(r)}${hex(g)}${hex(b)}${a < 255 ? hex(a) : ""}`;
}
export async function applyEditorTheme(
  monaco: Monaco,
  theme: "light" | "dark",
  element: HTMLElement,
  name: string,
  isCurrent: () => boolean,
  language: string,
  themes: ViewerThemes = defaultViewerThemes,
) {
  const { instance, themeName } = await getViewerHighlighter(
    language,
    theme,
    themes,
  );
  await getViewerHighlighter(
    language,
    theme === "dark" ? "light" : "dark",
    themes,
  );
  if (!isCurrent()) return;
  await instance.loadTheme({ ...instance.getTheme(themeName), name });
  if (!isCurrent()) return;
  let native = nativeMethods.get(monaco);
  if (!native) {
    native = { setTheme: monaco.editor.setTheme, create: monaco.editor.create };
    nativeMethods.set(monaco, native);
  }
  // Re-register newly loaded grammars without stacking Shiki's global wrappers.
  monaco.editor.setTheme = native.setTheme;
  monaco.editor.create = native.create;
  registerEditorHighlighter(instance, monaco);
  const base = textmateThemeToMonacoTheme(
    instance.getTheme(name),
  ) as editor.IStandaloneThemeData;
  const colors = base.colors ?? {};
  const bg =
    cssVar(element, "--background") || colors["editor.background"] || "#ffffff";
  const fg =
    cssVar(element, "--foreground") || colors["editor.foreground"] || "#222222";
  const muted = cssVar(element, "--muted") || bg;
  const border = cssVar(element, "--border") || fg;
  const accent = cssVar(element, "--accent") || muted;
  const primary = cssVar(element, "--primary") || fg;
  monaco.editor.defineTheme(name, {
    ...base,
    colors: {
      ...colors,
      "editor.background": bg,
      "editor.foreground": fg,
      "editor.lineHighlightBackground": muted,
      "editor.selectionBackground": `${primary.slice(0, 7)}33`,
      "editorCursor.foreground": fg,
      "editorIndentGuide.background1": border,
      "editorSuggestWidget.background": bg,
      "editorSuggestWidget.foreground": fg,
      "editorSuggestWidget.selectedBackground": accent,
      "editorHoverWidget.background": bg,
      "editorWidget.background": bg,
      "editorGutter.background": bg,
      "scrollbar.shadow": "#00000000",
    },
  });
  monaco.editor.setTheme(name);
}

type Disposable = { dispose: () => void };

export function createEditorWorkerLifecycle({
  modelCount,
  onModelDispose,
}: {
  modelCount: () => number;
  onModelDispose: (listener: () => void) => Disposable;
}) {
  const workers = new Set<Worker>();
  const resets = new Map<string, () => void>();
  let owners = 0;
  let queued = false;
  let models: Disposable | undefined;

  function releaseIdle() {
    if (owners || modelCount()) return;
    if (workers.size) {
      // Public defaults notifications clear Monaco's cached language clients
      // before termination, so reopening never reuses a terminated Worker.
      for (const reset of resets.values()) reset();
      for (const worker of [...workers]) worker.terminate();
    }
    models?.dispose();
    models = undefined;
  }
  function schedule() {
    if (queued) return;
    queued = true;
    queueMicrotask(() => {
      queued = false;
      releaseIdle();
    });
  }
  function observeModels() {
    models ??= onModelDispose(() => {
      if (!owners) schedule();
    });
  }
  return {
    acquire() {
      owners++;
      observeModels();
      let released = false;
      return () => {
        if (released) return;
        released = true;
        owners--;
        if (!owners) schedule();
      };
    },
    track<T extends Worker>(worker: T): T {
      const terminate = worker.terminate.bind(worker);
      let terminated = false;
      worker.terminate = () => {
        if (terminated) return;
        terminated = true;
        workers.delete(worker);
        terminate();
      };
      workers.add(worker);
      observeModels();
      if (!owners) schedule();
      return worker;
    },
    registerReset(language: string, reset: () => void) {
      resets.set(language, reset);
      if (!owners && workers.size) schedule();
    },
  };
}

import type { SvgGlassRenderer } from "@/lib/glass/svg-renderer";

let svg: Promise<SvgGlassRenderer | undefined> | undefined;
let instance: SvgGlassRenderer | undefined;
let failed = false;
let controller = new AbortController();

/** CSS-only material where reduced transparency or forced colors are preferred. */
export function glassBaseOnly() {
  return Boolean(
    window.matchMedia?.(
      "(prefers-reduced-transparency: reduce), (forced-colors: active)",
    ).matches,
  );
}

/** The shared native SVG renderer, unless the browser cannot paint SVG backdrops. */
export async function prepareGlassRenderer() {
  if (glassBaseOnly() || failed) return;
  const session = controller;
  svg ??= (async () => {
    try {
      const { SvgGlassRenderer } = await import("@/lib/glass/svg-renderer");
      const renderer = await SvgGlassRenderer.create();
      if (session.signal.aborted) {
        renderer.destroy();
        return;
      }
      instance = renderer;
      return renderer;
    } catch {
      if (!session.signal.aborted) failed = true;
    }
  })();
  const renderer = await svg;
  if (!session.signal.aborted && !failed) return renderer;
}

export function failGlassRenderer() {
  failed = true;
  instance?.destroy();
  instance = undefined;
}

export function releaseGlassRenderers() {
  controller.abort();
  instance?.destroy();
  instance = undefined;
  svg = undefined;
  failed = false;
  controller = new AbortController();
}

export type GlassColor = [number, number, number, number];

let colorContext: CanvasRenderingContext2D | null | undefined;

/** Resolves any CSS color, including oklch and color-mix, to sRGB channels. */
export function parseGlassColor(color: string): GlassColor {
  if (!color || color === "transparent") return [0, 0, 0, 0];
  if (colorContext === undefined) {
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = 1;
    colorContext = canvas.getContext("2d", { willReadFrequently: true });
  }
  const context = colorContext;
  if (!context) return [0.5, 0.5, 0.5, 1];
  context.clearRect(0, 0, 1, 1);
  context.fillStyle = "#000";
  context.fillStyle = color;
  context.fillRect(0, 0, 1, 1);
  const bytes = context.getImageData(0, 0, 1, 1).data;
  return [bytes[0] / 255, bytes[1] / 255, bytes[2] / 255, bytes[3] / 255];
}

