var(
      --glass-initial-edge-shadow,
      inset 0.8px 0.8px 0.4px -0.6px var(--glass-initial-edge-color),
      inset -0.8px -0.8px 0.4px -0.6px
        color-mix(in srgb, var(--glass-initial-edge-color) 70%, transparent),
      0 1px 3px -1px rgb(0 0 0 / 0.1)
    ),
    var(--glass-press, 0 0 #0000), var(--tw-inset-shadow, 0 0 #0000),
    var(--tw-inset-ring-shadow, 0 0 #0000),
    var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000),
    var(--tw-shadow, 0 0 #0000)

[data-glass=\"true\"][data-glass-state].--glass-icon-glow:
drop-shadow(
      0 0 1px color-mix(in srgb, var(--glass-halo) 85%, transparent)
    )
    drop-shadow(
      0 0 2.5px color-mix(in srgb, var(--glass-halo) 50%, transparent)
    )

[data-frosted=\"true\"].background-color:
color-mix(
    in srgb,
    var(--frosted-tint) var(--frosted-opacity, 65%),
    transparent
  )

[data-frosted=\"true\"].box-shadow:
var(--frosted-shadow), var(--glass-press, 0 0 #0000),
    var(--tw-inset-shadow, 0 0 #0000), var(--tw-inset-ring-shadow, 0 0 #0000),
    var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000),
    var(--tw-shadow, 0 0 #0000)
